  constructor(servers) {
    this.servers = servers.map((s) => ({ ...s, healthy: true }));
    this.cursor = 0;
  }

  markHealth(id, healthy) {
    const server = this.servers.find((s) => s.id === id);
    if (server) server.healthy = healthy;
  }

  nextServer() {
    // TODO: cycle through this.servers starting at this.cursor, advancing
    // this.cursor each time, but only ever RETURN a server whose
    // healthy === true. If none are healthy, throw new Error("no healthy servers available").
    return this.servers[0];
  }
}

