class WeightedRoundRobinBalancer {
  constructor(servers) {
    // servers: [{ id, weight }]
    this.servers = servers.map((s) => ({ ...s, healthy: true }));
    this.cursor = 0;
    this.remainingInSlot = 0;
  }

  markHealth(id, healthy) {
    const server = this.servers.find((s) => s.id === id);
    if (server) server.healthy = healthy;
  }

  // TODO: expand this.servers into an explicit sequence where each server
  // appears `weight` times (e.g. weight 2 appears twice as often as weight 1),
  // interleaved fairly (not all of one server's copies bunched together),
  // and return the array. Only include entries for currently healthy servers.
  buildSequence() {
    return this.servers.map((s) => s.id);
  }
}

