class WeightedRoundRobinBalancer {
  constructor(servers) {
    this.servers = servers.map((s) => ({ ...s, healthy: true }));
    this.cursor = 0;
    this.remainingInSlot = 0;
  }

  markHealth(id, healthy) {
    const server = this.servers.find((s) => s.id === id);
    if (server) server.healthy = healthy;
  }

  buildSequence() {
    const healthy = this.servers.filter((s) => s.healthy);
    if (healthy.length === 0) return [];
    const maxWeight = Math.max(...healthy.map((s) => s.weight));
    const sequence = [];
    for (let round = 0; round < maxWeight; round++) {
      for (const server of healthy) {
        if (round < server.weight) sequence.push(server.id);
      }
    }
    return sequence;
  }
}

